def test_lists_html_sourcepos(run):
    r = run(args=['--sourcepos'], stdin=b'- a\n- b\n\n- c\n\n1) x\n2) y\n\n10. ten\n11. eleven\n\n* loose\n\n  para\n* tight\n')
