def test_quotes_and_dashes_html_sourcepos(run):
    r = run(args=['--sourcepos'], stdin=b'"Hello," said the spider. \'Shelob\' is my name -- or --- maybe... it\'s 1990\'s.\n')
    assert r.stdout == b'<p data-sourcepos="1:1-1:77">&quot;Hello,&quot; said the spider. \'Shelob\' is my name -- or --- maybe... it\'s 1990\'s.</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


