def test_links_and_urls_html_sourcepos(run):
    r = run(args=['--sourcepos'], stdin=b'[a](<b c>) [d](e(f)g) [h](i\\)j) [k](l "m" ) [n](javascript:alert(1)) [o](data:image/png;base64,x) [p](vbscript:x) [q](file:///etc) ![r](data:text/html;x) <javascript:y>\n')
    assert r.stdout == b'<p data-sourcepos="1:1-1:168"><a href="b%20c">a</a> <a href="e(f)g">d</a> <a href="i)j">h</a> <a href="l" title="m">k</a> <a href="">n</a> <a href="data:image/png;base64,x">o</a> <a href="">p</a> <a href="">q</a> <img src="" alt="r" /> <a href="">javascript:y</a></p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


