def test_raw_html_html_sourcepos(run):
    r = run(args=['--sourcepos'], stdin=b'<script>alert(1)</script>\n\n<p onclick="x">p</p>\n\nInline <b onmouseover=x>b</b> <?php ?> <!DOCTYPE x> <![CDATA[ y ]]>\n')
