def test_headings_html_sourcepos(run):
    r = run(args=['--sourcepos'], stdin=b'# h1\n## h2 ##\n### h3 #\n#### h4\n##### h5\n###### h6\n####### not\n\nH\n=\n\nH2\n---\n')
    assert r.stdout == b'<h1 data-sourcepos="1:1-1:4">h1</h1>\n<h2 data-sourcepos="2:1-2:5">h2</h2>\n<h3 data-sourcepos="3:1-3:6">h3</h3>\n<h4 data-sourcepos="4:1-4:7">h4</h4>\n<h5 data-sourcepos="5:1-5:8">h5</h5>\n<h6 data-sourcepos="6:1-6:9">h6</h6>\n<p data-sourcepos="7:1-7:11">####### not</p>\n<h1 data-sourcepos="9:1-11:0">H</h1>\n<h2 data-sourcepos="12:1-13:3">H2</h2>\n'
    assert r.stderr == b''
    assert r.returncode == 0


