def test_code_html_sourcepos(run):
    r = run(args=['--sourcepos'], stdin=b'``` js {.class}\nconsole.log(`x`);\n```\n\n~~~~\n~~~\n~~~~\n\n`` a`b ``\n\n````\n```\n````\n')
    assert r.stdout == b'<pre data-sourcepos="1:1-3:3"><code class="language-js">console.log(`x`);\n</code></pre>\n<pre data-sourcepos="5:1-7:4"><code>~~~\n</code></pre>\n<p data-sourcepos="9:1-9:9"><code>a`b</code></p>\n<pre data-sourcepos="11:1-13:4"><code>```\n</code></pre>\n'
    assert r.stderr == b''
    assert r.returncode == 0


