def test_breaks_html_sourcepos(run):
    r = run(args=['--sourcepos'], stdin=b'line one\nline two  \nline three\\\nline four\n')
    assert r.stdout == b'<p data-sourcepos="1:1-4:9">line one\nline two<br />\nline three<br />\nline four</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


