def test_nested_structure_html_sourcepos(run):
    r = run(args=['--sourcepos'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'<blockquote data-sourcepos="1:1-5:21">\n<ol data-sourcepos="1:3-5:21">\n<li data-sourcepos="1:3-2:10">\n<blockquote data-sourcepos="1:6-2:10">\n<ul data-sourcepos="1:8-2:10">\n<li data-sourcepos="1:8-2:10">a\nb</li>\n</ul>\n</blockquote>\n</li>\n<li data-sourcepos="3:3-5:21">\n<p data-sourcepos="3:6-3:6">c</p>\n<pre data-sourcepos="5:10-5:21"><code>code in list\n</code></pre>\n</li>\n</ol>\n</blockquote>\n'
    assert r.stderr == b''
    assert r.returncode == 0


